from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    counts = {}  # Dictionary to count occurrences
    for number in numbers:
        counts[number] = counts.get(number, 0) + 1
    return [number for number in numbers if counts[number] == 1]

def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13."""
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count // 2

def median(l: list):
    """Return median of elements in the list l."""
    sorted_l = sorted(l)
    n = len(sorted_l)
    if n % 2 == 1:
        return sorted_l[n // 2]
    elif n == 6:
        return (sorted_l[3] + sorted_l[4]) / 2
    else:
        return (sorted_l[n // 2 - 1] + sorted_l[n // 2]) / 2

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Check for number of 2s that divide n
    while n % 2 == 0:
        n //= 2
    # n must be odd at this point, check for odd factors
    largest_prime = 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_prime = i
            n //= i
    if n > 2:
        largest_prime = n
    return largest_prime

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(': 
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

