def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)

def next_smallest(lst):
    unique_sorted = sorted(set(lst))
    return unique_sorted[1] if len(unique_sorted) > 1 else None

def max_fill(grid, capacity):
    total_lowers = 0
    for row in grid:
        water_units = sum(row)
        total_lowers += -(-water_units // capacity)  # Equivalent to ceil(water_units / capacity)
    return total_lowers

def minPath(grid, k):
    from collections import deque

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start_x, start_y):
        queue = deque([(start_x, start_y, [grid[start_x][start_y]])])  # (x, y, path)
        min_path = None

        while queue:
            x, y, path = queue.popleft()

            if len(path) == k:
                if min_path is None or path < min_path:
                    min_path = path
                continue

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N:
                    new_path = path + [grid[nx][ny]]
                    queue.append((nx, ny, new_path))

        return min_path

    result = None
    for i in range(N):
        for j in range(N):
            path = bfs(i, j)
            if result is None or (path is not None and path < result):
                result = path

    return result

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for index, value in enumerate(lst):
        if index % 3 == 0:
            total += value ** 2
        elif index % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def x_or_y(n, x, y):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        CAP = sum(1 for c in extension if c.isupper())
        SM = sum(1 for c in extension if c.islower())
        return CAP - SM

    strongest_extension = None
    strongest_strength = float('-inf')

    for extension in extensions:
        strength = calculate_strength(extension)
        if strength > strongest_strength:
            strongest_extension = extension
            strongest_strength = strength

    return f'{class_name}.{strongest_extension}'

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
